package ditaa;

import java.util.*;

/** A set of cells backed by a hash set (iteration order follows hashing). */
public class CellSet implements Iterable<Cell> {
    public static final int TYPE_CLOSED = 0;
    public static final int TYPE_OPEN = 1;
    public static final int TYPE_MIXED = 2;
    public static final int TYPE_HAS_CLOSED_AREA = 3;
    public static final int TYPE_UNDETERMINED = 4;

    private final HashSet<Cell> cells = new HashSet<Cell>();
    private int type = TYPE_UNDETERMINED;
    private boolean typeIsValid = false;

    public CellSet() {}

    public CellSet(CellSet other) {
        addAll(other);
    }

    public Iterator<Cell> iterator() { return cells.iterator(); }
    public int size() { return cells.size(); }
    public boolean isEmpty() { return cells.isEmpty(); }
    public boolean contains(Cell c) { return c != null && cells.contains(c); }
    public boolean add(Cell c) { typeIsValid = false; return cells.add(c); }
    public boolean remove(Cell c) { typeIsValid = false; return cells.remove(c); }
    public void addAll(CellSet other) { typeIsValid = false; for (Cell c : other) cells.add(c); }
    public void clear() { typeIsValid = false; cells.clear(); }

    public Cell getFirst() {
        Iterator<Cell> it = cells.iterator();
        return it.hasNext() ? it.next() : null;
    }

    public boolean containsAll(CellSet other) {
        for (Cell c : other) if (!cells.contains(c)) return false;
        return true;
    }

    public boolean sameAs(CellSet other) {
        return size() == other.size() && containsAll(other);
    }

    public void subtractSet(CellSet other) {
        typeIsValid = false;
        for (Cell c : other) cells.remove(c);
    }

    public int getMinX() { int m = Integer.MAX_VALUE; for (Cell c : cells) if (c.x < m) m = c.x; return m; }
    public int getMaxX() { int m = Integer.MIN_VALUE; for (Cell c : cells) if (c.x > m) m = c.x; return m; }
    public int getMinY() { int m = Integer.MAX_VALUE; for (Cell c : cells) if (c.y < m) m = c.y; return m; }
    public int getMaxY() { int m = Integer.MIN_VALUE; for (Cell c : cells) if (c.y > m) m = c.y; return m; }
    public int getWidth() { return getMaxX() - getMinX(); }
    public int getHeight() { return getMaxY() - getMinY(); }

    public CellSet copy() {
        CellSet s = new CellSet();
        for (Cell c : cells) s.cells.add(c);
        return s;
    }

    public void translate(int dx, int dy) {
        ArrayList<Cell> list = new ArrayList<Cell>(cells);
        cells.clear();
        for (Cell c : list) cells.add(new Cell(c.x + dx, c.y + dy));
        typeIsValid = false;
    }

    public CellSet makeScaledOneThirdEquivalent() {
        TextGrid grid = new TextGrid(getMaxX() * 3 + 3, getMaxY() * 3 + 3);
        grid.fillCellsWith(this, '*');
        CellSet result = new CellSet();
        for (Cell c : cells) {
            result.cells.add(new Cell(c.x / 3, c.y / 3));
        }
        return result;
    }

    public ArrayList<CellSet> breakIntoDistinctBoundaries() {
        ArrayList<CellSet> result = new ArrayList<CellSet>();
        TextGrid boundaryGrid = new TextGrid(getMaxX() + 2, getMaxY() + 2);
        boundaryGrid.fillCellsWith(this, '*');
        for (Cell cell : cells) {
            if (boundaryGrid.isBlank(cell.x, cell.y)) continue;
            CellSet set = boundaryGrid.fillContinuousArea(cell.x, cell.y, ' ');
            result.add(set);
        }
        return result;
    }

    public int getType(TextGrid grid) {
        if (typeIsValid) return type;
        typeIsValid = true;
        if (size() == 1) { type = TYPE_OPEN; return type; }
        int typeTrace = getTypeAccordingToTraceMethod(grid);
        if (typeTrace == TYPE_OPEN) { type = TYPE_OPEN; return type; }
        if (typeTrace == TYPE_CLOSED) { type = TYPE_CLOSED; return type; }
        if (typeTrace == TYPE_UNDETERMINED) {
            int typeFill = getTypeAccordingToFillMethod(grid);
            if (typeFill == TYPE_HAS_CLOSED_AREA) { type = TYPE_MIXED; return type; }
            else if (typeFill == TYPE_OPEN) { type = TYPE_OPEN; return type; }
        }
        type = TYPE_UNDETERMINED;
        return type;
    }

    private int getTypeAccordingToTraceMethod(TextGrid grid) {
        if (size() < 2) return TYPE_OPEN;
        TextGrid workGrid = TextGrid.makeSameSizeAs(grid);
        grid.copyCellsTo(this, workGrid);
        // start with a line end if one exists, otherwise with the first cell
        Cell start = null;
        for (Cell cell : cells) {
            if (workGrid.isLinesEnd(cell)) start = cell;
        }
        if (start == null) start = getFirst();
        Cell previous = start;
        Cell cell;
        CellSet nextCells = workGrid.followCell(previous, null);
        if (nextCells.size() == 0) return TYPE_OPEN;
        cell = nextCells.getFirst();
        int guard = 0;
        while (!cell.equals(start)) {
            nextCells = workGrid.followCell(cell, previous);
            if (nextCells.size() == 0) return TYPE_OPEN;
            else if (nextCells.size() == 1) {
                previous = cell;
                cell = nextCells.getFirst();
            } else {
                return TYPE_UNDETERMINED;
            }
            if (++guard > 1000000) return TYPE_UNDETERMINED;
        }
        return TYPE_CLOSED;
    }

    private int getTypeAccordingToFillMethod(TextGrid grid) {
        if (size() == 0) return TYPE_OPEN;
        CellSet temp = copy();
        temp.translate(-getMinX() + 1, -getMinY() + 1);
        TextGrid subGrid = grid.getSubGrid(getMinX() - 1, getMinY() - 1, getWidth() + 3, getHeight() + 3);
        AbstractionGrid abstraction = new AbstractionGrid(subGrid, temp);
        TextGrid tempGrid = abstraction.getCopyOfInternalBuffer();
        int width = tempGrid.getWidth();
        int height = tempGrid.getHeight();
        Cell fillCell = null;
        outer:
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                if (tempGrid.isBlank(x, y)) { fillCell = new Cell(x, y); break outer; }
            }
        }
        if (fillCell == null) return TYPE_UNDETERMINED;
        tempGrid.fillContinuousArea(fillCell.x, fillCell.y, '*');
        int blanks = tempGrid.getAllBlanks().size();
        if (blanks > 0) return TYPE_HAS_CLOSED_AREA;
        return TYPE_OPEN;
    }

    /** Splits a mixed set into its open parts (lines leading to intersections) and the remaining (closed) part. */
    public ArrayList<CellSet> breakTrulyMixedBoundaries(TextGrid grid) {
        ArrayList<CellSet> result = new ArrayList<CellSet>();
        CellSet visitedEnds = new CellSet();
        TextGrid workGrid = TextGrid.makeSameSizeAs(grid);
        grid.copyCellsTo(this, workGrid);
        for (Cell start : cells) {
            if (workGrid.isLinesEnd(start) && !visitedEnds.contains(start)) {
                Cell previous = start;
                Cell cell;
                CellSet set = new CellSet();
                set.add(start);
                CellSet nextCells = workGrid.followCell(previous, null);
                if (nextCells.size() == 0) {
                    throw new IllegalArgumentException("This shape is either open but multipart or has only one cell, and cannot be processed by this method");
                }
                cell = nextCells.getFirst();
                set.add(cell);
                boolean finished = false;
                if (workGrid.isLinesEnd(cell)) {
                    visitedEnds.add(cell);
                    finished = true;
                }
                int guard = 0;
                while (!finished) {
                    nextCells = workGrid.followCell(cell, previous);
                    if (nextCells.size() == 1) {
                        set.add(cell);
                        previous = cell;
                        cell = nextCells.getFirst();
                        if (workGrid.isLinesEnd(cell)) {
                            visitedEnds.add(cell);
                            finished = true;
                        }
                    } else if (nextCells.size() > 1) {
                        finished = true;
                    } else {
                        finished = true;
                    }
                    if (++guard > 1000000) finished = true;
                }
                result.add(set);
            }
        }
        // subtract all open sets from this set
        CellSet whatsLeft = new CellSet(this);
        for (CellSet set : result) whatsLeft.subtractSet(set);
        result.add(whatsLeft);
        return result;
    }

    public static ArrayList<CellSet> removeDuplicateSets(ArrayList<CellSet> list) {
        ArrayList<CellSet> result = new ArrayList<CellSet>();
        for (CellSet set : list) {
            boolean dup = false;
            for (CellSet r : result) if (r.sameAs(set)) { dup = true; break; }
            if (!dup) result.add(set);
        }
        return result;
    }

    @Override
    public String toString() {
        return cells.toString();
    }
}
