    /** Returns the cells connected to the given cell, excluding the blocked one. */
    public CellSet followCell(Cell cell, Cell blocked) {
        CellSet result = new CellSet();
        int x = cell.x, y = cell.y;
        char c = get(x, y);
        boolean n = false, s = false, e = false, w = false;
        if (c == '+') {
            if (isIntersection(x, y) || isCrossOnLine(x, y) || isCorner(x, y) || isStub(x, y)) {
                n = entryN(x, y); s = entryS(x, y); e = entryE(x, y); w = entryW(x, y);
                if (isCross(x, y) || isT(x, y) || isInverseT(x, y) || isK(x, y) || isInverseK(x, y)) {
                    // intersections connect only to real lines on their arms
                    n = vLine(x, y - 1); s = vLine(x, y + 1); e = hLine(x + 1, y); w = hLine(x - 1, y);
                } else if (isCorner1(x, y)) { n = false; w = false; }
                else if (isCorner2(x, y)) { n = false; e = false; }
                else if (isCorner3(x, y)) { s = false; e = false; }
                else if (isCorner4(x, y)) { s = false; w = false; }
                else if (isHorizontalCrossOnLine(x, y)) { n = false; s = false; }
                else if (isVerticalCrossOnLine(x, y)) { e = false; w = false; }
            }
        } else if (c == '/' || c == '\\') {
            if (isCorner1(x, y)) { e = true; s = true; }
            else if (isCorner2(x, y)) { w = true; s = true; }
            else if (isCorner3(x, y)) { w = true; n = true; }
            else if (isCorner4(x, y)) { e = true; n = true; }
        } else if (in(c, HORIZONTAL_LINES)) {
            e = entryE(x, y); w = entryW(x, y);
        } else if (in(c, VERTICAL_LINES)) {
            n = entryN(x, y); s = entryS(x, y);
        } else if (c == '*') {
            n = entryN(x, y); s = entryS(x, y); e = entryE(x, y); w = entryW(x, y);
        }
        if (n) result.add(cell.north());
        if (s) result.add(cell.south());
        if (e) result.add(cell.east());
        if (w) result.add(cell.west());
        if (blocked != null) result.remove(blocked);
        return result;
