package ditaa;

import java.util.*;
import java.util.regex.*;

/** A rectangular grid of characters together with the ASCII-art predicates used by the diagram builder. */
public class TextGrid {

    private ArrayList<StringBuilder> rows;

    public static final String BOUNDARY_CHARS = "/\\|-*=:";
    public static final String UNDISPUTABLE_BOUNDARIES = "|-*=:";
    public static final String HORIZONTAL_LINES = "-=";
    public static final String VERTICAL_LINES = "|:";
    public static final String ARROWHEADS = "<>^vV";
    public static final String CORNER_CHARS = "\\/+";
    public static final String DASHED_LINES = ":~=";
    public static final String VERTICAL_ENTRY = "|:+\\/";
    public static final String HORIZONTAL_ENTRY = "-=+\\/";
    public static final String LINEISH = "-=/\\+|:";

    private static final HashMap<String, String> humanColorCodes = new HashMap<String, String>();
    private static final HashSet<String> markupTags = new HashSet<String>();
    static {
        humanColorCodes.put("GRE", "9D9");
        humanColorCodes.put("BLU", "55B");
        humanColorCodes.put("PNK", "FAA");
        humanColorCodes.put("RED", "E32");
        humanColorCodes.put("YEL", "FF3");
        humanColorCodes.put("BLK", "000");
        markupTags.add("d");
        markupTags.add("s");
        markupTags.add("io");
        markupTags.add("c");
        markupTags.add("mo");
        markupTags.add("tr");
        markupTags.add("o");
    }

    public static class CellStringPair {
        public final Cell cell;
        public final String string;
        public CellStringPair(Cell cell, String string) { this.cell = cell; this.string = string; }
    }

    public static class CellColorPair {
        public final Cell cell;
        public final java.awt.Color color;
        public CellColorPair(Cell cell, java.awt.Color color) { this.cell = cell; this.color = color; }
    }

    public static class CellTagPair {
        public final Cell cell;
        public final String tag;
        public CellTagPair(Cell cell, String tag) { this.cell = cell; this.tag = tag; }
    }

    public TextGrid() {
        rows = new ArrayList<StringBuilder>();
    }

    public TextGrid(int width, int height) {
        rows = new ArrayList<StringBuilder>();
        StringBuilder blank = new StringBuilder();
        for (int i = 0; i < width; i++) blank.append(' ');
        for (int i = 0; i < height; i++) rows.add(new StringBuilder(blank.toString()));
    }

    public TextGrid(TextGrid other) {
        rows = new ArrayList<StringBuilder>();
        for (StringBuilder r : other.rows) rows.add(new StringBuilder(r.toString()));
    }

    public static TextGrid makeSameSizeAs(TextGrid grid) {
        return new TextGrid(grid.getWidth(), grid.getHeight());
    }

    public int getWidth() { return rows.size() == 0 ? 0 : rows.get(0).length(); }
    public int getHeight() { return rows.size(); }

    public char get(int x, int y) {
        if (x < 0 || y < 0 || y >= getHeight() || x >= getWidth()) return 0;
        return rows.get(y).charAt(x);
    }
    public char get(Cell c) { return get(c.x, c.y); }

    public void set(int x, int y, char c) {
        if (x < 0 || y < 0 || y >= getHeight() || x >= getWidth()) return;
        rows.get(y).setCharAt(x, c);
    }
    public void set(Cell cell, char c) { set(cell.x, cell.y, c); }

    public String getRow(int y) { return rows.get(y).toString(); }

    public boolean isOutOfBounds(int x, int y) {
        return x < 0 || y < 0 || x >= getWidth() || y >= getHeight();
    }
    public boolean isOutOfBounds(Cell c) { return isOutOfBounds(c.x, c.y); }

    // ---------------------------------------------------------------- loading

    /** Builds the grid from the raw text lines, expanding tabs and adding a blank border. */
    public void initialiseWithLines(ArrayList<String> lines, int tabSize) {
        // find the last non-blank line; everything after it is dropped
        int lastNonBlank = 0;
        for (int i = 0; i < lines.size(); i++) {
            if (lines.get(i).trim().length() > 0) lastNonBlank = i;
        }
        lines = new ArrayList<String>(lines.subList(0, lastNonBlank + 1));

        // expand tabs
        ArrayList<String> expanded = new ArrayList<String>();
        for (String line : lines) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < line.length(); i++) {
                char c = line.charAt(i);
                if (c == '\t') {
                    int spaces = tabSize - (sb.length() % tabSize);
                    if (tabSize <= 0) spaces = 0;
                    for (int k = 0; k < spaces; k++) sb.append(' ');
                } else {
                    sb.append(c);
                }
            }
            expanded.add(sb.toString());
        }

        int maxLength = 0;
        for (String line : expanded) if (line.length() > maxLength) maxLength = line.length();

        int border = 2;
        int width = maxLength + 2 * border;
        rows = new ArrayList<StringBuilder>();
        StringBuilder blankLine = new StringBuilder();
        for (int i = 0; i < width; i++) blankLine.append(' ');
        for (int i = 0; i < border; i++) rows.add(new StringBuilder(blankLine.toString()));
        for (String line : expanded) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < border; i++) sb.append(' ');
            sb.append(line);
            while (sb.length() < width) sb.append(' ');
            rows.add(sb);
        }
        for (int i = 0; i < border; i++) rows.add(new StringBuilder(blankLine.toString()));
    }

    // --------------------------------------------------------------- basics

    public boolean isBlank(int x, int y) {
        char c = get(x, y);
        if (c == 0) return false;
        return c == ' ';
    }
    public boolean isBlank(Cell c) { return isBlank(c.x, c.y); }

    private static boolean in(char c, String set) {
        return c != 0 && set.indexOf(c) >= 0;
    }

    public boolean isHorizontalLine(int x, int y) { return in(get(x, y), HORIZONTAL_LINES); }
    public boolean isHorizontalLine(Cell c) { return isHorizontalLine(c.x, c.y); }
    public boolean isVerticalLine(int x, int y) { return in(get(x, y), VERTICAL_LINES); }
    public boolean isVerticalLine(Cell c) { return isVerticalLine(c.x, c.y); }
    public boolean isLine(int x, int y) { return isHorizontalLine(x, y) || isVerticalLine(x, y); }
    public boolean isLine(Cell c) { return isLine(c.x, c.y); }
    public boolean isCornerChar(int x, int y) { return in(get(x, y), CORNER_CHARS); }
    public boolean isArrowheadChar(int x, int y) { return in(get(x, y), ARROWHEADS); }
    public boolean isPointMarker(int x, int y) { return get(x, y) == '*'; }
    public boolean isPointMarker(Cell c) { return isPointMarker(c.x, c.y); }
    public boolean isDashedLineChar(int x, int y) { return in(get(x, y), DASHED_LINES); }

    private boolean vEntry(int x, int y) { return in(get(x, y), VERTICAL_ENTRY); }
    private boolean hEntry(int x, int y) { return in(get(x, y), HORIZONTAL_ENTRY); }
    private boolean vLine(int x, int y) { return in(get(x, y), VERTICAL_LINES); }
    private boolean hLine(int x, int y) { return in(get(x, y), HORIZONTAL_LINES); }
    private boolean lineish(int x, int y) { return in(get(x, y), LINEISH); }

    // entries into (x,y) from the four directions
    private boolean entryN(int x, int y) { return vEntry(x, y - 1); }
    private boolean entryS(int x, int y) { return vEntry(x, y + 1); }
    private boolean entryW(int x, int y) { return hEntry(x - 1, y); }
    private boolean entryE(int x, int y) { return hEntry(x + 1, y); }

    // ------------------------------------------------------- intersections

    public boolean isCross(int x, int y) {
        return get(x, y) == '+' && vLine(x, y - 1) && vLine(x, y + 1) && hLine(x - 1, y) && hLine(x + 1, y);
    }
    public boolean isT(int x, int y) { // W, E, S
        return get(x, y) == '+' && hLine(x - 1, y) && hLine(x + 1, y) && vLine(x, y + 1) && !vLine(x, y - 1);
    }
    public boolean isInverseT(int x, int y) { // W, E, N
        return get(x, y) == '+' && hLine(x - 1, y) && hLine(x + 1, y) && vLine(x, y - 1) && !vLine(x, y + 1);
    }
    public boolean isK(int x, int y) { // N, S, E
        return get(x, y) == '+' && vLine(x, y - 1) && vLine(x, y + 1) && hLine(x + 1, y) && !hLine(x - 1, y);
    }
    public boolean isInverseK(int x, int y) { // N, S, W
        return get(x, y) == '+' && vLine(x, y - 1) && vLine(x, y + 1) && hLine(x - 1, y) && !hLine(x + 1, y);
    }
    public boolean isIntersection(int x, int y) {
        return isCross(x, y) || isT(x, y) || isInverseT(x, y) || isK(x, y) || isInverseK(x, y);
    }
    public boolean isIntersection(Cell c) { return isIntersection(c.x, c.y); }

    // --------------------------------------------------------------- corners

    /** top-left corner: connects east and south */
    public boolean isCorner1(int x, int y) {
        char c = get(x, y);
        if (c != '+' && c != '/') return false;
        return entryE(x, y) && entryS(x, y) && !vLine(x, y - 1) && !hLine(x - 1, y);
    }
    /** top-right corner: connects west and south */
    public boolean isCorner2(int x, int y) {
        char c = get(x, y);
        if (c != '+' && c != '\\') return false;
        return entryW(x, y) && entryS(x, y) && !vLine(x, y - 1) && !hLine(x + 1, y);
    }
    /** bottom-right corner: connects west and north */
    public boolean isCorner3(int x, int y) {
        char c = get(x, y);
        if (c != '+' && c != '/') return false;
        return entryW(x, y) && entryN(x, y) && !vLine(x, y + 1) && !hLine(x + 1, y);
    }
    /** bottom-left corner: connects east and north */
    public boolean isCorner4(int x, int y) {
        char c = get(x, y);
        if (c != '+' && c != '\\') return false;
        return entryE(x, y) && entryN(x, y) && !vLine(x, y + 1) && !hLine(x - 1, y);
    }
    public boolean isCorner(int x, int y) {
        return isCorner1(x, y) || isCorner2(x, y) || isCorner3(x, y) || isCorner4(x, y);
    }
    public boolean isCorner(Cell c) { return isCorner(c.x, c.y); }
    public boolean isRoundCorner(int x, int y) {
        char c = get(x, y);
        return (c == '/' || c == '\\') && isCorner(x, y);
    }
    public boolean isRoundCorner(Cell c) { return isRoundCorner(c.x, c.y); }
    public boolean isNormalCorner(int x, int y) { return get(x, y) == '+' && isCorner(x, y); }

    // ------------------------------------------------------- cross on line

    public boolean isHorizontalCrossOnLine(int x, int y) {
        return get(x, y) == '+' && entryW(x, y) && entryE(x, y) && !vLine(x, y - 1) && !vLine(x, y + 1);
    }
    public boolean isVerticalCrossOnLine(int x, int y) {
        return get(x, y) == '+' && entryN(x, y) && entryS(x, y) && !hLine(x - 1, y) && !hLine(x + 1, y);
    }
    public boolean isCrossOnLine(int x, int y) {
        return isHorizontalCrossOnLine(x, y) || isVerticalCrossOnLine(x, y);
    }

    // ---------------------------------------------------------------- stubs

    public boolean isStub(int x, int y) {
        if (get(x, y) != '+') return false;
        boolean n = entryN(x, y), s = entryS(x, y), w = entryW(x, y), e = entryE(x, y);
        if (n && !s && !vLine(x - 1, y) && !vLine(x + 1, y) && !lineish(x - 1, y - 1) && !lineish(x + 1, y - 1)) return true;
        if (s && !n && !vLine(x - 1, y) && !vLine(x + 1, y) && !lineish(x - 1, y + 1) && !lineish(x + 1, y + 1)) return true;
        if (w && !e && !hLine(x, y - 1) && !hLine(x, y + 1) && !lineish(x - 1, y - 1) && !lineish(x - 1, y + 1)) return true;
        if (e && !w && !hLine(x, y - 1) && !hLine(x, y + 1) && !lineish(x + 1, y - 1) && !lineish(x + 1, y + 1)) return true;
        return false;
    }

    // ---------------------------------------------------------------- stars

    public boolean isHorizontalStarOnLine(int x, int y) {
        return get(x, y) == '*' && (entryW(x, y) || entryE(x, y));
    }
    public boolean isVerticalStarOnLine(int x, int y) {
        return get(x, y) == '*' && (entryN(x, y) || entryS(x, y));
    }
    public boolean isStarOnLine(int x, int y) {
        return isHorizontalStarOnLine(x, y) || isVerticalStarOnLine(x, y);
    }
    public boolean isStarOnLine(Cell c) { return isStarOnLine(c.x, c.y); }

    // ------------------------------------------------------------ boundary

    public boolean isBoundary(int x, int y) {
        char c = get(x, y);
        if (c == 0) return false;
        if (c == '+') {
            return isIntersection(x, y) || isCorner(x, y) || isCrossOnLine(x, y) || isStub(x, y);
        }
        if (c == '/' || c == '\\') {
            return isCorner(x, y);
        }
        return in(c, UNDISPUTABLE_BOUNDARIES);
    }
    public boolean isBoundary(Cell c) { return isBoundary(c.x, c.y); }

    public CellSet getAllBoundaries() {
        CellSet set = new CellSet();
        int w = getWidth(), h = getHeight();
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++)
                if (isBoundary(x, y)) set.add(new Cell(x, y));
        return set;
    }

    public CellSet getAllNonBlank() {
        CellSet set = new CellSet();
        int w = getWidth(), h = getHeight();
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++)
                if (!isBlank(x, y)) set.add(new Cell(x, y));
        return set;
    }

    public CellSet getAllBlanks() {
        CellSet set = new CellSet();
        int w = getWidth(), h = getHeight();
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++)
                if (isBlank(x, y)) set.add(new Cell(x, y));
        return set;
    }

    public CellSet getAllBlanksBetweenCharacters() {
        CellSet set = new CellSet();
        int w = getWidth(), h = getHeight();
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++)
                if (isBlank(x, y) && !isBlank(x - 1, y) && !isBlank(x + 1, y)) set.add(new Cell(x, y));
        return set;
    }

    // ----------------------------------------------------------- arrowheads

    public boolean isArrowhead(int x, int y) {
        char c = get(x, y);
        if (c == '>' || c == '<' || c == '^') return true;
        if (c == 'v' || c == 'V') return vEntry(x, y - 1);
        return false;
    }
    public boolean isArrowhead(Cell c) { return isArrowhead(c.x, c.y); }

    public ArrayList<Cell> findArrowheads() {
        ArrayList<Cell> result = new ArrayList<Cell>();
        int w = getWidth(), h = getHeight();
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++)
                if (isArrowhead(x, y)) result.add(new Cell(x, y));
        return result;
    }

    public ArrayList<Cell> getPointMarkersOnLine() {
        ArrayList<Cell> result = new ArrayList<Cell>();
        int w = getWidth(), h = getHeight();
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++)
                if (isStarOnLine(x, y)) result.add(new Cell(x, y));
        return result;
    }

    // ---------------------------------------------------------- following

    public boolean isLinesEnd(Cell cell) {
        return followCell(cell, null).size() == 1;
    }

    /** Returns the cells connected to the given cell, excluding the blocked one. */
    public CellSet followCell(Cell cell, Cell blocked) {
        CellSet result = new CellSet();
        int x = cell.x, y = cell.y;
        char c = get(x, y);
        boolean n = false, s = false, e = false, w = false;
        if (c == '+') {
            if (isIntersection(x, y) || isCrossOnLine(x, y) || isCorner(x, y) || isStub(x, y)) {
                n = entryN(x, y); s = entryS(x, y); e = entryE(x, y); w = entryW(x, y);
                if (isCross(x, y) || isT(x, y) || isInverseT(x, y) || isK(x, y) || isInverseK(x, y)) {
                    // intersections connect only to real lines on their arms
                    n = vLine(x, y - 1); s = vLine(x, y + 1); e = hLine(x + 1, y); w = hLine(x - 1, y);
                } else if (isCorner1(x, y)) { n = false; w = false; }
                else if (isCorner2(x, y)) { n = false; e = false; }
                else if (isCorner3(x, y)) { s = false; e = false; }
                else if (isCorner4(x, y)) { s = false; w = false; }
                else if (isHorizontalCrossOnLine(x, y)) { n = false; s = false; }
                else if (isVerticalCrossOnLine(x, y)) { e = false; w = false; }
            }
        } else if (c == '/' || c == '\\') {
            if (isCorner1(x, y)) { e = true; s = true; }
            else if (isCorner2(x, y)) { w = true; s = true; }
            else if (isCorner3(x, y)) { w = true; n = true; }
            else if (isCorner4(x, y)) { e = true; n = true; }
        } else if (in(c, HORIZONTAL_LINES)) {
            e = entryE(x, y); w = entryW(x, y);
        } else if (in(c, VERTICAL_LINES)) {
            n = entryN(x, y); s = entryS(x, y);
        } else if (c == '*') {
            n = entryN(x, y); s = entryS(x, y); e = entryE(x, y); w = entryW(x, y);
        }
        if (n) result.add(cell.north());
        if (s) result.add(cell.south());
        if (e) result.add(cell.east());
        if (w) result.add(cell.west());
        if (blocked != null) result.remove(blocked);
        return result;
    }

    // ------------------------------------------------------------ filling

    public CellSet fillContinuousArea(int x, int y, char newChar) {
        CellSet filled = new CellSet();
        if (isOutOfBounds(x, y)) return filled;
        char oldChar = get(x, y);
        if (oldChar == newChar) return filled;
        ArrayDeque<Cell> stack = new ArrayDeque<Cell>();
        stack.push(new Cell(x, y));
        while (!stack.isEmpty()) {
            Cell cell = stack.pop();
            if (get(cell) != oldChar) continue;
            set(cell, newChar);
            filled.add(cell);
            Cell nc = cell.north(), sc = cell.south(), ec = cell.east(), wc = cell.west();
            if (get(nc) == oldChar) stack.push(nc);
            if (get(sc) == oldChar) stack.push(sc);
            if (get(ec) == oldChar) stack.push(ec);
            if (get(wc) == oldChar) stack.push(wc);
        }
        return filled;
    }

    public void fillCellsWith(CellSet cells, char c) {
        for (Cell cell : cells) set(cell, c);
    }

    public void copyCellsTo(CellSet cells, TextGrid grid) {
        for (Cell cell : cells) grid.set(cell, get(cell));
    }

    public TextGrid getSubGrid(int x, int y, int width, int height) {
        TextGrid grid = new TextGrid(width, height);
        for (int yi = 0; yi < height; yi++)
            for (int xi = 0; xi < width; xi++)
                grid.set(xi, yi, get(x + xi, y + yi));
        return grid;
    }

    // --------------------------------------------------------- color codes

    private static final Pattern colorCodePattern = Pattern.compile("c[A-F0-9]{3}");

    public void replaceHumanColorCodes() {
        int h = getHeight();
        for (int y = 0; y < h; y++) {
            String row = getRow(y);
            for (Map.Entry<String, String> e : humanColorCodes.entrySet()) {
                String human = "c" + e.getKey();
                String code = "c" + e.getValue();
                row = row.replace(human, code);
            }
            rows.set(y, new StringBuilder(row));
        }
    }

    public ArrayList<CellColorPair> findColorCodes() {
        ArrayList<CellColorPair> result = new ArrayList<CellColorPair>();
        int h = getHeight();
        for (int y = 0; y < h; y++) {
            String row = getRow(y);
            Matcher m = colorCodePattern.matcher(row);
            while (m.find()) {
                int start = m.start();
                String code = m.group();
                char cR = code.charAt(1), cG = code.charAt(2), cB = code.charAt(3);
                int r = Integer.parseInt("" + cR + cR, 16);
                int g = Integer.parseInt("" + cG + cG, 16);
                int b = Integer.parseInt("" + cB + cB, 16);
                result.add(new CellColorPair(new Cell(start, y), new java.awt.Color(r, g, b)));
            }
        }
        return result;
    }

    public void removeColorCodes() {
        for (CellColorPair pair : findColorCodes()) {
            int x = pair.cell.x, y = pair.cell.y;
            set(x++, y, ' '); set(x++, y, ' '); set(x++, y, ' '); set(x, y, ' ');
        }
    }

    // ---------------------------------------------------------- markup tags

    private static final Pattern tagPattern = Pattern.compile("\\{(.+?)\\}");

    public ArrayList<CellTagPair> findMarkupTags() {
        ArrayList<CellTagPair> result = new ArrayList<CellTagPair>();
        int h = getHeight();
        for (int y = 0; y < h; y++) {
            String row = getRow(y);
            Matcher m = tagPattern.matcher(row);
            while (m.find()) {
                String tag = m.group(1);
                if (markupTags.contains(tag)) {
                    result.add(new CellTagPair(new Cell(m.start(), y), tag));
                }
            }
        }
        return result;
    }

    public void removeMarkupTags() {
        for (CellTagPair pair : findMarkupTags()) {
            int length = pair.tag.length() + 2;
            for (int i = 0; i < length; i++) set(pair.cell.x + i, pair.cell.y, ' ');
        }
    }

    // ------------------------------------------------------------- bullets

    public boolean isBullet(int x, int y) {
        char c = get(x, y);
        return (c == 'o' || c == '*') && isBlank(x + 1, y) && isBlank(x - 1, y) && !isBlank(x + 2, y) && get(x + 2, y) != 0;
    }

    public void replaceBullets() {
        int w = getWidth(), h = getHeight();
        for (int y = 0; y < h; y++) {
            for (int x = 0; x < w; x++) {
                if (isBullet(x, y)) {
                    set(x, y, ' ');
                    set(x + 1, y, '\u2022');
                }
            }
        }
    }

    // ---------------------------------------------------------- removals

    public void removeNonText() {
        removeArrowheads();
        removeColorCodes();
        removeBoundaries();
        removeMarkupTags();
    }

    public void removeArrowheads() {
        for (Cell c : findArrowheads()) set(c, ' ');
    }

    public void removeBoundaries() {
        ArrayList<Cell> toRemove = new ArrayList<Cell>();
        int w = getWidth(), h = getHeight();
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++)
                if (isBoundary(x, y)) toRemove.add(new Cell(x, y));
        for (Cell c : toRemove) set(c, ' ');
    }

    // -------------------------------------------------------------- strings

    public boolean isStringsStart(Cell cell) { return !isBlank(cell) && isBlank(cell.west()); }
    public boolean isStringsEnd(Cell cell) { return !isBlank(cell) && isBlank(cell.east()); }

    public int otherStringsStartInTheSameColumn(Cell cell) {
        if (!isStringsStart(cell)) return 0;
        int result = 0;
        int h = getHeight();
        for (int y = 0; y < h; y++) {
            Cell c = new Cell(cell.x, y);
            if (!c.equals(cell) && isStringsStart(c)) result++;
        }
        return result;
    }

    public int otherStringsEndInTheSameColumn(Cell cell) {
        if (!isStringsEnd(cell)) return 0;
        int result = 0;
        int h = getHeight();
        for (int y = 0; y < h; y++) {
            Cell c = new Cell(cell.x, y);
            if (!c.equals(cell) && isStringsEnd(c)) result++;
        }
        return result;
    }

    public ArrayList<CellStringPair> findStrings() {
        ArrayList<CellStringPair> result = new ArrayList<CellStringPair>();
        int w = getWidth(), h = getHeight();
        for (int y = 0; y < h; y++) {
            for (int x = 0; x < w; x++) {
                if (!isBlank(x, y)) {
                    Cell start = new Cell(x, y);
                    StringBuilder str = new StringBuilder();
                    str.append(get(x, y));
                    char c = get(++x, y);
                    boolean finished = false;
                    while (!finished) {
                        str.append(c);
                        c = get(++x, y);
                        if (c == 0) finished = true;
                        else if (isBlank(x, y) && (x + 1 >= w || isBlank(x + 1, y))) finished = true;
                    }
                    result.add(new CellStringPair(start, str.toString()));
                }
            }
        }
        return result;
    }

    // -------------------------------------------------------------- debug

    public String getDebugString() {
        StringBuilder sb = new StringBuilder();
        int w = getWidth(), h = getHeight();
        sb.append("    ");
        for (int x = 0; x < w; x++) sb.append(x % 10);
        sb.append('\n');
        for (int y = 0; y < h; y++) {
            String num = String.valueOf(y);
            if (y < 10) num = " " + num;
            sb.append(num).append(" (").append(getRow(y)).append(")\n");
        }
        return sb.toString();
    }

    public void printDebug() {
        System.out.print(getDebugString());
    }
}
