    private void setCenter(Cell c) { grid.set(c.x * 3 + 1, c.y * 3 + 1, '*'); }
    private void setNorth(Cell c) { grid.set(c.x * 3 + 1, c.y * 3, '*'); }
    private void setSouth(Cell c) { grid.set(c.x * 3 + 1, c.y * 3 + 2, '*'); }
    private void setWest(Cell c) { grid.set(c.x * 3, c.y * 3 + 1, '*'); }
    private void setEast(Cell c) { grid.set(c.x * 3 + 2, c.y * 3 + 1, '*'); }

