package ditaa;

import java.awt.Color;
import java.awt.geom.*;
import java.util.*;

/** A shape made of points: either a closed polygon or an open polyline. */
public class DiagramShape extends DiagramComponent {
    public static final int TYPE_SIMPLE = 0;
    public static final int TYPE_ARROWHEAD = 1;
    public static final int TYPE_POINT_MARKER = 2;
    public static final int TYPE_DOCUMENT = 3;
    public static final int TYPE_STORAGE = 4;
    public static final int TYPE_IO = 5;
    public static final int TYPE_DECISION = 6;
    public static final int TYPE_MANUAL_OPERATION = 7;
    public static final int TYPE_TRAPEZOID = 8;
    public static final int TYPE_ELLIPSE = 9;
    public static final int TYPE_CUSTOM = 9999;

    private int type = TYPE_SIMPLE;
    private Color fillColor = null;
    private Color strokeColor = Color.black;
    private boolean closed = false;
    private boolean strokeDashed = false;
    protected ArrayList<ShapePoint> points = new ArrayList<ShapePoint>();

    public DiagramShape() {}

    public int getType() { return type; }
    public void setType(int t) { type = t; }
    public Color getFillColor() { return fillColor; }
    public void setFillColor(Color c) { fillColor = c; }
    public Color getStrokeColor() { return strokeColor; }
    public void setStrokeColor(Color c) { strokeColor = c; }
    public boolean isClosed() { return closed; }
    public void setClosed(boolean c) { closed = c; }
    public boolean isStrokeDashed() { return strokeDashed; }
    public void setStrokeDashed(boolean d) { strokeDashed = d; }
    public ArrayList<ShapePoint> getPoints() { return points; }
    public void addToPoints(ShapePoint p) { points.add(p); }
    public ShapePoint getPoint(int i) { return points.get(i); }
    public void setPoint(int i, ShapePoint p) { points.set(i, p); }

    public boolean dropsShadow() {
        return isClosed() && type != TYPE_ARROWHEAD && type != TYPE_POINT_MARKER && !strokeDashed;
    }

    public boolean isRectangle() {
        if (points.size() != 4) return false;
        ShapePoint p1 = points.get(0), p2 = points.get(1), p3 = points.get(2), p4 = points.get(3);
        return (p1.isInLineWith(p2) && p2.isInLineWith(p3) && p3.isInLineWith(p4) && p4.isInLineWith(p1));
    }

    public static DiagramShape createArrowhead(TextGrid grid, Cell cell, int cellWidth, int cellHeight) {
        if (!grid.isArrowhead(cell)) return null;
        char c = grid.get(cell);
        DiagramShape shape = new DiagramShape();
        shape.setType(TYPE_ARROWHEAD);
        shape.setClosed(true);
        shape.setFillColor(Color.black);
        float minX = cell.x * cellWidth, maxX = minX + cellWidth, midX = minX + cellWidth / 2;
        float minY = cell.y * cellHeight, maxY = minY + cellHeight, midY = minY + cellHeight / 2;
        if (c == '>') {
            shape.addToPoints(new ShapePoint(minX, minY));
            shape.addToPoints(new ShapePoint(maxX, midY));
            shape.addToPoints(new ShapePoint(minX, maxY));
        } else if (c == '<') {
            shape.addToPoints(new ShapePoint(maxX, minY));
            shape.addToPoints(new ShapePoint(minX, midY));
            shape.addToPoints(new ShapePoint(maxX, maxY));
        } else if (c == '^') {
            shape.addToPoints(new ShapePoint(midX, minY));
            shape.addToPoints(new ShapePoint(minX, maxY));
            shape.addToPoints(new ShapePoint(maxX, maxY));
        } else { // v V
            shape.addToPoints(new ShapePoint(minX, minY));
            shape.addToPoints(new ShapePoint(midX, maxY));
            shape.addToPoints(new ShapePoint(maxX, minY));
        }
        return shape;
    }

    public static DiagramShape createSmallLine(TextGrid grid, Cell cell, int cellWidth, int cellHeight) {
        DiagramShape shape = new DiagramShape();
        char c = grid.get(cell);
        if (c == '-') {
            shape.addToPoints(new ShapePoint(cell.x * cellWidth, cell.y * cellHeight + cellHeight / 2));
            shape.addToPoints(new ShapePoint(cell.x * cellWidth + cellWidth - 1, cell.y * cellHeight + cellHeight / 2));
        } else if (c == '|') {
            shape.addToPoints(new ShapePoint(cell.x * cellWidth + cellWidth / 2, cell.y * cellHeight));
            shape.addToPoints(new ShapePoint(cell.x * cellWidth + cellWidth / 2, cell.y * cellHeight + cellHeight - 1));
        } else {
            return null;
        }
        return shape;
    }

    // ------------------------------------------------------------- geometry

    public double getArea() {
        int n = points.size();
        if (n < 3) return 0;
        double area = 0;
        for (int i = 0; i < n; i++) {
            ShapePoint p1 = points.get(i);
            ShapePoint p2 = points.get((i + 1) % n);
            area += (double) p1.x * p2.y - (double) p2.x * p1.y;
        }
        return Math.abs(area / 2.0);
    }

    public boolean isSmallerThan(DiagramShape other) {
        return getArea() < other.getArea();
    }

    public Rectangle2D getBounds() {
        return makeIntoPath().getBounds2D();
    }

    public GeneralPath makeIntoPath() {
        int size = points.size();
        if (size < 2) return null;
        GeneralPath path = new GeneralPath();
        ShapePoint p = points.get(0);
        path.moveTo(p.x, p.y);
        for (int i = 1; i < size; i++) {
            p = points.get(i);
            path.lineTo(p.x, p.y);
        }
        if (closed && size > 2) path.closePath();
        return path;
    }

    public boolean contains(ShapePoint point) {
        GeneralPath path = makeIntoPath();
        if (path == null) return false;
        return path.contains(point.x, point.y);
    }

    public boolean contains(Rectangle2D rect) {
        GeneralPath path = makeIntoPath();
        if (path == null) return false;
        return path.contains(rect);
    }

    public boolean intersects(Rectangle2D rect) {
        GeneralPath path = makeIntoPath();
        if (path == null) return false;
        return path.intersects(rect);
    }

    public ArrayList<ShapeEdge> getEdges() {
        ArrayList<ShapeEdge> edges = new ArrayList<ShapeEdge>();
        int size = points.size();
        for (int i = 0; i + 1 < size; i++) {
            edges.add(new ShapeEdge(points.get(i), points.get(i + 1), this));
        }
        if (closed && size > 1) {
            edges.add(new ShapeEdge(points.get(size - 1), points.get(0), this));
        }
        return edges;
    }

    // --------------------------------------------------------- render path

    public GeneralPath makeIntoRenderPath(Diagram diagram, RenderingOptions options) {
        int size = points.size();
        if (type == TYPE_POINT_MARKER) {
            ShapePoint p = points.get(0);
            float d = (float) diagram.getCellWidth() * 0.7f;
            Ellipse2D.Float e = new Ellipse2D.Float(p.x - d / 2, p.y - d / 2, d, d);
            GeneralPath path = new GeneralPath();
            path.append(e, false);
            return path;
        }
        if (size == 4) {
            if (type == TYPE_DOCUMENT) return makeDocumentPath(diagram);
            if (type == TYPE_STORAGE) return makeStoragePath(diagram);
            if (type == TYPE_IO) return makeIOPath(diagram, options);
            if (type == TYPE_DECISION) return makeDecisionPath(diagram);
            if (type == TYPE_MANUAL_OPERATION) return makeManualOperationPath(diagram, options);
            if (type == TYPE_TRAPEZOID) return makeTrapezoidPath(diagram, options);
            if (type == TYPE_ELLIPSE) return makeEllipsePath(diagram);
        }
        if (size < 2) return null;

        GeneralPath path = new GeneralPath();
        ShapePoint point = points.get(0);
        ShapePoint previous = points.get(size - 1);
        ShapePoint next = points.get(1);
        if (point.getType() == ShapePoint.TYPE_ROUND && closed) {
            ShapePoint entry = getCellEdgePointBetween(point, previous, diagram);
            ShapePoint exit = getCellEdgePointBetween(point, next, diagram);
            path.moveTo(entry.x, entry.y);
            path.quadTo(point.x, point.y, exit.x, exit.y);
        } else {
            path.moveTo(point.x, point.y);
        }
        for (int i = 1; i < size; i++) {
            previous = points.get(i - 1);
            point = points.get(i);
            if (point.getType() == ShapePoint.TYPE_ROUND) {
                next = (i + 1 < size) ? points.get(i + 1) : (closed ? points.get(0) : null);
                if (next != null) {
                    ShapePoint entry = getCellEdgePointBetween(point, previous, diagram);
                    ShapePoint exit = getCellEdgePointBetween(point, next, diagram);
                    path.lineTo(entry.x, entry.y);
                    path.quadTo(point.x, point.y, exit.x, exit.y);
                    // the line to the next point is drawn immediately after the curve
                    ShapePoint target;
                    if (next.getType() == ShapePoint.TYPE_ROUND) target = getCellEdgePointBetween(next, point, diagram);
                    else target = next;
                    path.lineTo(target.x, target.y);
                } else {
                    path.lineTo(point.x, point.y);
                }
            } else {
                path.lineTo(point.x, point.y);
            }
        }
        if (closed) path.closePath();
        return path;
    }

    private ShapePoint getCellEdgePointBetween(ShapePoint point, ShapePoint other, Diagram diagram) {
        float cw = diagram.getCellWidth(), ch = diagram.getCellHeight();
        if (point.isNorthOf(other)) return new ShapePoint(point.x, point.y + (int) (ch / 2));
        if (point.isSouthOf(other)) return new ShapePoint(point.x, point.y - (int) (ch / 2));
        if (point.isWestOf(other)) return new ShapePoint(point.x + (int) (cw / 2), point.y);
        if (point.isEastOf(other)) return new ShapePoint(point.x - (int) (cw / 2), point.y);
        return new ShapePoint(point.x, point.y);
    }

    private int[] intBounds() {
        int minX = Integer.MAX_VALUE, minY = Integer.MAX_VALUE, maxX = Integer.MIN_VALUE, maxY = Integer.MIN_VALUE;
        for (ShapePoint p : points) {
            minX = Math.min(minX, (int) p.x); maxX = Math.max(maxX, (int) p.x);
            minY = Math.min(minY, (int) p.y); maxY = Math.max(maxY, (int) p.y);
        }
        return new int[]{minX, minY, maxX, maxY};
    }

    private GeneralPath makeDocumentPath(Diagram diagram) {
        int[] b = intBounds();
        int minX = b[0], minY = b[1], maxX = b[2], maxY = b[3];
        int w = maxX - minX, h = maxY - minY;
        int midX = (minX + maxX) / 2;
        int dx = w / 6, dy = h / 8;
        GeneralPath path = new GeneralPath();
        path.moveTo(minX, minY);
        path.lineTo(maxX, minY);
        path.lineTo(maxX, maxY);
        path.quadTo(midX + dx, maxY - dy, midX, maxY);
        path.quadTo(midX - dx, maxY + dy, minX, maxY);
        path.closePath();
        return path;
    }

    private GeneralPath makeStoragePath(Diagram diagram) {
        int[] b = intBounds();
        int minX = b[0], minY = b[1], maxX = b[2], maxY = b[3];
        int w = maxX - minX;
        int ch = diagram.getCellHeight();
        int dx = w / 6;
        int dyTop = ch / 2;
        int dyBottom = (int) (ch * 5 / 7f);
        GeneralPath path = new GeneralPath();
        path.moveTo(minX, minY);
        path.curveTo(minX + dx, minY + dyTop, maxX - dx, minY + dyTop, maxX, minY);
        path.curveTo(maxX - dx, minY - dyTop, minX + dx, minY - dyTop, minX, minY);
        path.moveTo(minX, minY);
        path.lineTo(minX, maxY);
        path.curveTo(minX + dx, maxY + dyBottom, maxX - dx, maxY + dyBottom, maxX, maxY);
        path.lineTo(maxX, minY);
        return path;
    }

    private float slopeOffset(int[] b, Diagram diagram, RenderingOptions options) {
        if (options.isFixedSlope()) {
            return (b[3] - b[1]) / 8f;
        }
        return diagram.getCellWidth() / 2f;
    }

    private GeneralPath makeIOPath(Diagram diagram, RenderingOptions options) {
        int[] b = intBounds();
        float off = slopeOffset(b, diagram, options);
        GeneralPath path = new GeneralPath();
        path.moveTo(b[0] + off, b[1]);
        path.lineTo(b[2] + off, b[1]);
        path.lineTo(b[2] - off, b[3]);
        path.lineTo(b[0] - off, b[3]);
        path.closePath();
        return path;
    }

    private GeneralPath makeManualOperationPath(Diagram diagram, RenderingOptions options) {
        int[] b = intBounds();
        float off = slopeOffset(b, diagram, options);
        GeneralPath path = new GeneralPath();
        path.moveTo(b[0] - off, b[1]);
        path.lineTo(b[2] + off, b[1]);
        path.lineTo(b[2] - off, b[3]);
        path.lineTo(b[0] + off, b[3]);
        path.closePath();
        return path;
    }

    private GeneralPath makeTrapezoidPath(Diagram diagram, RenderingOptions options) {
        int[] b = intBounds();
        float off = slopeOffset(b, diagram, options);
        GeneralPath path = new GeneralPath();
        path.moveTo(b[0] + off, b[1]);
        path.lineTo(b[2] - off, b[1]);
        path.lineTo(b[2] + off, b[3]);
        path.lineTo(b[0] - off, b[3]);
        path.closePath();
        return path;
    }

    private GeneralPath makeDecisionPath(Diagram diagram) {
        int[] b = intBounds();
        int midX = (b[0] + b[2]) / 2, midY = (b[1] + b[3]) / 2;
        GeneralPath path = new GeneralPath();
        path.moveTo(b[0], midY);
        path.lineTo(midX, b[1]);
        path.lineTo(b[2], midY);
        path.lineTo(midX, b[3]);
        path.closePath();
        return path;
    }

    private GeneralPath makeEllipsePath(Diagram diagram) {
        int[] b = intBounds();
        Ellipse2D.Float e = new Ellipse2D.Float(b[0], b[1], b[2] - b[0], b[3] - b[1]);
        GeneralPath path = new GeneralPath();
        path.append(e, false);
        return path;
    }

    // ------------------------------------------------------------- anchors

    public void connectEndsToAnchors(TextGrid grid, Diagram diagram) {
        if (isClosed()) return;
        if (points.size() < 2) return;
        ShapePoint start = points.get(0);
        ShapePoint next = points.get(1);
        ShapePoint end = points.get(points.size() - 1);
        ShapePoint beforeEnd = points.get(points.size() - 2);
        connectEndToAnchors(grid, diagram, next, start);
        connectEndToAnchors(grid, diagram, beforeEnd, end);
    }

    private void connectEndToAnchors(TextGrid grid, Diagram diagram, ShapePoint linkedTo, ShapePoint point) {
        if (isClosed()) return;
        Cell anchorCell = getPossibleAnchorCell(point, linkedTo, diagram);
        if (anchorCell == null) return;
        if (grid.isArrowhead(anchorCell) || grid.isCorner(anchorCell) || grid.isIntersection(anchorCell)) {
            point.x = diagram.getCellMidX(anchorCell);
            point.y = diagram.getCellMidY(anchorCell);
            point.setLocked(true);
        }
    }

    private Cell getPossibleAnchorCell(ShapePoint point, ShapePoint linkedTo, Diagram diagram) {
        Cell cell = diagram.getCellFor(point);
        if (cell == null) throw new IllegalArgumentException("ShapePoint cannot be null");
        if (point.isNorthOf(linkedTo)) return cell.north();
        if (point.isSouthOf(linkedTo)) return cell.south();
        if (point.isWestOf(linkedTo)) return cell.west();
        if (point.isEastOf(linkedTo)) return cell.east();
        return null;
    }

    @Override
    public boolean equals(Object o) {
        if (!(o instanceof DiagramShape)) return false;
        DiagramShape s = (DiagramShape) o;
        if (s.points.size() != points.size()) return false;
        for (int i = 0; i < points.size(); i++) if (!points.get(i).equals(s.points.get(i))) return false;
        return true;
    }

    @Override
    public int hashCode() { return points.size(); }

    @Override
    public String toString() {
        return "DiagramShape" + points + (closed ? " closed" : "") + " type=" + type;
    }
}
