package ditaa;

/** Base class for things that end up drawn in the diagram. */
public abstract class DiagramComponent {
    protected static ShapePoint makePointForCell(Cell cell, TextGrid grid, int cellWidth, int cellHeight, boolean allRound) {
        float x = cell.x * cellWidth + cellWidth / 2;
        float y = cell.y * cellHeight + cellHeight / 2;
        if (grid.isCorner(cell) && (allRound || grid.isRoundCorner(cell))) {
            return new ShapePoint(x, y, ShapePoint.TYPE_ROUND);
        }
        return new ShapePoint(x, y, ShapePoint.TYPE_NORMAL);
    }

    /** Builds a closed shape from a set of boundary cells by following the boundary. */
    public static DiagramComponent createClosedFromBoundaryCells(TextGrid grid, CellSet cells, int cellWidth, int cellHeight, boolean allRound) {
        if (cells.getType(grid) == CellSet.TYPE_OPEN) throw new IllegalArgumentException("CellSet is open and cannot be handled by this method");
        if (cells.size() < 2) return null;

        DiagramShape shape = new DiagramShape();
        shape.setClosed(true);
        if (grid.containsAtLeastOneDashedLine(cells)) shape.setStrokeDashed(true);

        TextGrid workGrid = new TextGrid(grid.getWidth(), grid.getHeight());
        grid.copyCellsTo(cells, workGrid);

        Cell start = cells.getFirst();
        if (workGrid.isCornerLike(start)) shape.addToPoints(makePointForCell(start, workGrid, cellWidth, cellHeight, allRound));

        Cell previous = start;
        CellSet nextCells = workGrid.followCell(previous, null);
        if (nextCells.size() == 0) return null;
        Cell cell = nextCells.getFirst();
        if (workGrid.isCornerLike(cell)) shape.addToPoints(makePointForCell(cell, workGrid, cellWidth, cellHeight, allRound));

        int guard = 0;
        while (!cell.equals(start)) {
            nextCells = workGrid.followCell(cell, previous);
            if (nextCells.size() == 1) {
                previous = cell;
                cell = nextCells.getFirst();
                if (!cell.equals(start) && workGrid.isCornerLike(cell)) {
                    shape.addToPoints(makePointForCell(cell, workGrid, cellWidth, cellHeight, allRound));
                }
            } else if (nextCells.size() == 0) {
                return null;
            } else {
                // more than one possible direction: cannot follow unambiguously
                return null;
            }
            if (++guard > 1000000) return null;
        }
        return shape;
    }
}
