package ditaa;

public class ShapeEdge {
    public static final int TYPE_HORIZONTAL = 0;
    public static final int TYPE_VERTICAL = 1;
    public static final int TYPE_SLOPED = 2;

    private ShapePoint start;
    private ShapePoint end;
    private DiagramShape owner;

    public ShapeEdge(ShapePoint start, ShapePoint end, DiagramShape owner) {
        this.start = start;
        this.end = end;
        this.owner = owner;
    }

    public ShapePoint getStartPoint() { return start; }
    public ShapePoint getEndPoint() { return end; }
    public DiagramShape getOwner() { return owner; }

    public int getType() {
        if (start.x == end.x) return TYPE_VERTICAL;
        if (start.y == end.y) return TYPE_HORIZONTAL;
        return TYPE_SLOPED;
    }
    public boolean isHorizontal() { return getType() == TYPE_HORIZONTAL; }
    public boolean isVertical() { return getType() == TYPE_VERTICAL; }

    public ShapePoint getMiddle() {
        return new ShapePoint((start.x + end.x) / 2, (start.y + end.y) / 2);
    }

    public boolean touchesWith(ShapeEdge other) {
        if (equals(other)) return false;
        if (getType() == TYPE_SLOPED || other.getType() == TYPE_SLOPED) return false;
        if (getType() != other.getType()) return false;
        if (isHorizontal()) {
            if (start.y != other.start.y) return false;
            float min1 = Math.min(start.x, end.x), max1 = Math.max(start.x, end.x);
            float min2 = Math.min(other.start.x, other.end.x), max2 = Math.max(other.start.x, other.end.x);
            return (min2 < max1 && min1 < max2);
        } else {
            if (start.x != other.start.x) return false;
            float min1 = Math.min(start.y, end.y), max1 = Math.max(start.y, end.y);
            float min2 = Math.min(other.start.y, other.end.y), max2 = Math.max(other.start.y, other.end.y);
            return (min2 < max1 && min1 < max2);
        }
    }

    public void moveInwardsBy(float offset) {
        if (getType() == TYPE_SLOPED) return;
        ShapePoint middle = getMiddle();
        float xOff = 0, yOff = 0;
        if (isVertical()) {
            if (owner.contains(new ShapePoint(middle.x + 1, middle.y))) xOff = offset;
            else xOff = -offset;
        } else {
            if (owner.contains(new ShapePoint(middle.x, middle.y + 1))) yOff = offset;
            else yOff = -offset;
        }
        start.x += xOff; start.y += yOff;
        end.x += xOff; end.y += yOff;
    }

    @Override
    public boolean equals(Object o) {
        if (!(o instanceof ShapeEdge)) return false;
        ShapeEdge e = (ShapeEdge) o;
        return (start.equals(e.start) && end.equals(e.end)) || (start.equals(e.end) && end.equals(e.start));
    }

    @Override
    public int hashCode() { return start.hashCode() + end.hashCode(); }
}
