public class FontMeasurer {
    private static final String FONT_FAMILY = "Dialog";
    private static final FontMeasurer instance = new FontMeasurer();

    private final FontRenderContext measureContext = new FontRenderContext(null, false, false);
    private final FontRenderContext outlineContext = new FontRenderContext(null, true, true);
    private final HashMap<Integer, Font> fontCache = new HashMap<Integer, Font>();

    public static FontMeasurer instance() { return instance; }

    public Font getFontOfSize(int size) {
        Font f = fontCache.get(size);
        if (f == null) {
            f = new Font(FONT_FAMILY, Font.BOLD, 12).deriveFont((float) size);
            fontCache.put(size, f);
        }
        return f;
    }

    public int getWidthFor(String str, Font font) {
        if (font == null) throw new NullPointerException();
        Rectangle2D r = font.getStringBounds(str, measureContext);
        return (int) r.getWidth();
    }

    public Rectangle2D getBoundsFor(String str, Font font) {
        return font.getStringBounds(str, measureContext);
    }

    public int getZHeight(Font font) {
        Rectangle r = font.createGlyphVector(outlineContext, "Z").getOutline().getBounds();
        return r.height;
    }

    private double heightMetric(int size) {
        return 0.928222656 * size + 0.433;
    }

    /** The font whose height best matches the given pixel height. */
    public Font getFontFor(int pixelHeight) {
        int size = 12;
        if (heightMetric(size) >= pixelHeight) {
            while (size > 0 && heightMetric(size) >= pixelHeight) size--;
        } else {
            while (heightMetric(size) < pixelHeight) size++;
        }
        if (size <= 0) return null;
        return getFontOfSize(size);
    }

    /** The largest font that renders the string within maxWidth pixels. */
    public Font getFontFor(int maxWidth, String string) {
        int size = 12;
        int width = getWidthFor(string, getFontOfSize(size));
        if (width > maxWidth) {
            while (size > 1 && getWidthFor(string, getFontOfSize(size)) >= maxWidth) size--;
            if (getWidthFor(string, getFontOfSize(size)) >= maxWidth && size <= 1) return null;
        } else {
            while (getWidthFor(string, getFontOfSize(size + 1)) <= maxWidth) size++;
        }
        return getFontOfSize(size);
    }

    /** Baseline offset (from the top of the cell) used for text rendered with the default font. */
    public int getDefaultBaselineOffset(int cellHeight, Font font) {
        int size = font.getSize();
        if (cellHeight >= 2 && cellHeight < DEFAULT_OFFSETS.length && DEFAULT_OFFSETS[cellHeight] > 0) {
            return DEFAULT_OFFSETS[cellHeight];
        }
        int zHeight = getZHeight(font);
        return (cellHeight + 1) / 2 + zHeight / 2;
    }

