public class DiagramText extends DiagramComponent {
    private int xPos;
    private int yPos;
    private String text;
    private Font font;
    private Color color = Color.black;
    private boolean hasOutline = false;
    private Color outlineColor = Color.white;

    public DiagramText(int x, int y, String text, Font font) {
        this.xPos = x;
        this.yPos = y;
        this.text = text;
        this.font = font;
    }

    public int getXPos() { return xPos; }
    public int getYPos() { return yPos; }
    public void setXPos(int x) { xPos = x; }
    public void setYPos(int y) { yPos = y; }
    public String getText() { return text; }
    public Font getFont() { return font; }
    public Color getColor() { return color; }
    public void setColor(Color c) { color = c; }
    public boolean hasOutline() { return hasOutline; }
    public void setHasOutline(boolean b) { hasOutline = b; }
    public Color getOutlineColor() { return outlineColor; }

    public Rectangle2D getBounds() {
        Rectangle2D r = FontMeasurer.instance().getBoundsFor(text, font);
        return new Rectangle2D.Double(r.getX() + xPos, r.getY() + yPos, r.getWidth(), r.getHeight());
    }

    public void centerHorizontallyBetween(int minX, int maxX) {
        int width = FontMeasurer.instance().getWidthFor(text, font);
        int center = Math.abs(maxX - minX) / 2;
        xPos += Math.abs(center - width / 2);
    }

    public void alignRightEdgeTo(int x) {
        int width = FontMeasurer.instance().getWidthFor(text, font);
        xPos = x - width;
    }

    /**
     * Vertical placement of the baseline within the cell.  The default-font case follows the
     * behaviour recorded from the reference implementation; smaller (width-reduced) fonts
     * are centred on the height of a capital letter.
     */
    public void centerVerticallyBetween(int minY, int maxY, boolean defaultFont) {
        int cellHeight = maxY - minY;
        int offset;
        if (defaultFont) {
            offset = FontMeasurer.instance().getDefaultBaselineOffset(cellHeight, font);
        } else {
            int zHeight = FontMeasurer.instance().getZHeight(font);
            offset = (cellHeight + 1) / 2 + zHeight / 2;
        }
        yPos = minY + offset;
    }

    @Override
    public String toString() {
        return "DiagramText[" + text + " @ " + xPos + "," + yPos + " size=" + font.getSize() + "]";
    }
}
