package ditaa;

import java.awt.Color;
import java.awt.Font;
import java.awt.geom.Rectangle2D;
import java.util.*;

/** Builds the vector representation of an ASCII diagram. */
public class Diagram {
    private ArrayList<DiagramShape> shapes = new ArrayList<DiagramShape>();
    private ArrayList<CompositeDiagramShape> compositeShapes = new ArrayList<CompositeDiagramShape>();
    private ArrayList<DiagramText> textObjects = new ArrayList<DiagramText>();

    private int width;
    private int height;
    private int cellWidth;
    private int cellHeight;

    public Diagram(TextGrid grid, ConversionOptions options) {
        this.cellWidth = options.renderingOptions.getCellWidth();
        this.cellHeight = options.renderingOptions.getCellHeight();
        boolean allCornersRound = options.processingOptions.areAllCornersRound();

        TextGrid workGrid = new TextGrid(grid);
        workGrid.replaceHumanColorCodes();

        width = grid.getWidth() * cellWidth;
        height = grid.getHeight() * cellHeight;

        // ----- find distinct boundary sets
        CellSet boundaries = workGrid.getAllBoundaries();
        AbstractionGrid temp = new AbstractionGrid(workGrid, boundaries);
        ArrayList<CellSet> boundarySetsStep1 = temp.getDistinctShapes();

        // ----- find all closed shapes using the fill method
        ArrayList<CellSet> boundarySetsStep2 = new ArrayList<CellSet>();
        for (CellSet set : boundarySetsStep1) {
            boundarySetsStep2.add(set);
            if (set.getType(workGrid) == CellSet.TYPE_OPEN) continue;
            boundarySetsStep2.addAll(findClosedSetsByFilling(workGrid, set));
        }
        boundarySetsStep2 = CellSet.removeDuplicateSets(boundarySetsStep2);

        // ----- classify
        ArrayList<CellSet> open = new ArrayList<CellSet>();
        ArrayList<CellSet> closed = new ArrayList<CellSet>();
        ArrayList<CellSet> mixed = new ArrayList<CellSet>();
        for (CellSet set : boundarySetsStep2) {
            int type = set.getType(workGrid);
            if (type == CellSet.TYPE_CLOSED) closed.add(set);
            else if (type == CellSet.TYPE_OPEN) open.add(set);
            else if (type == CellSet.TYPE_MIXED) mixed.add(set);
        }

        boolean hadToEliminateMixed = false;
        if (mixed.size() > 0 && closed.size() > 0) {
            for (CellSet set : mixed) {
                for (CellSet closedSet : closed) set.subtractSet(closedSet);
                if (set.getType(workGrid) == CellSet.TYPE_OPEN) {
                    boundarySetsStep2.remove(set);
                    boundarySetsStep2.addAll(breakIntoDistinctBoundaries(workGrid, set));
                    hadToEliminateMixed = true;
                }
            }
        } else if (mixed.size() > 0 && closed.size() == 0) {
            for (CellSet set : mixed) {
                boundarySetsStep2.remove(set);
                boundarySetsStep2.addAll(set.breakTrulyMixedBoundaries(workGrid));
                hadToEliminateMixed = true;
            }
        }
        if (hadToEliminateMixed) {
            open = new ArrayList<CellSet>();
            closed = new ArrayList<CellSet>();
            mixed = new ArrayList<CellSet>();
            for (CellSet set : boundarySetsStep2) {
                int type = set.getType(workGrid);
                if (type == CellSet.TYPE_CLOSED) closed.add(set);
                else if (type == CellSet.TYPE_OPEN) open.add(set);
                else if (type == CellSet.TYPE_MIXED) mixed.add(set);
            }
        }

        // ----- make shapes
        ArrayList<DiagramShape> closedShapes = new ArrayList<DiagramShape>();
        for (CellSet set : boundarySetsStep2) {
            int type = set.getType(workGrid);
            if (type == CellSet.TYPE_CLOSED) {
                DiagramComponent shape = DiagramComponent.createClosedFromBoundaryCells(workGrid, set, cellWidth, cellHeight, allCornersRound);
                if (shape != null) {
                    if (shape instanceof DiagramShape) {
                        addToShapes((DiagramShape) shape);
                        closedShapes.add((DiagramShape) shape);
                    } else if (shape instanceof CompositeDiagramShape) {
                        addToCompositeShapes((CompositeDiagramShape) shape);
                    }
                }
            } else if (type == CellSet.TYPE_OPEN) {
                DiagramComponent shape = CompositeDiagramShape.createOpenFromBoundaryCells(workGrid, set, cellWidth, cellHeight, allCornersRound);
                if (shape != null) {
                    if (shape instanceof CompositeDiagramShape) {
                        addToCompositeShapes((CompositeDiagramShape) shape);
                    } else if (shape instanceof DiagramShape) {
                        addToShapes((DiagramShape) shape);
                    }
                }
            }
        }

        // ----- color codes
        ArrayList<TextGrid.CellColorPair> colorPairs = workGrid.findColorCodes();
        for (TextGrid.CellColorPair pair : colorPairs) {
            ShapePoint point = new ShapePoint(getCellMidX(pair.cell), getCellMidY(pair.cell));
            DiagramShape containingShape = findSmallestShapeContaining(point);
            if (containingShape != null) containingShape.setFillColor(pair.color);
        }

        // ----- markup tags
        ArrayList<TextGrid.CellTagPair> markupPairs = workGrid.findMarkupTags();
        for (TextGrid.CellTagPair pair : markupPairs) {
            ShapePoint point = new ShapePoint(getCellMidX(pair.cell), getCellMidY(pair.cell));
            DiagramShape containingShape = findSmallestShapeContaining(point);
            if (containingShape == null) continue;
            if (pair.tag.equals("d")) containingShape.setType(DiagramShape.TYPE_DOCUMENT);
            else if (pair.tag.equals("s")) containingShape.setType(DiagramShape.TYPE_STORAGE);
            else if (pair.tag.equals("io")) containingShape.setType(DiagramShape.TYPE_IO);
            else if (pair.tag.equals("c")) containingShape.setType(DiagramShape.TYPE_DECISION);
            else if (pair.tag.equals("mo")) containingShape.setType(DiagramShape.TYPE_MANUAL_OPERATION);
            else if (pair.tag.equals("tr")) containingShape.setType(DiagramShape.TYPE_TRAPEZOID);
            else if (pair.tag.equals("o")) containingShape.setType(DiagramShape.TYPE_ELLIPSE);
        }

        // ----- arrowheads
        for (Cell cell : workGrid.findArrowheads()) {
            DiagramShape arrowhead = DiagramShape.createArrowhead(workGrid, cell, cellWidth, cellHeight);
            if (arrowhead != null) addToShapes(arrowhead);
            else System.err.println("Could not create arrowhead shape. Unexpected error.");
        }

        // ----- point markers
        for (Cell cell : grid.getPointMarkersOnLine()) {
            DiagramShape mark = new DiagramShape();
            mark.addToPoints(new ShapePoint(getCellMidX(cell), getCellMidY(cell)));
            mark.setType(DiagramShape.TYPE_POINT_MARKER);
            mark.setFillColor(Color.white);
            shapes.add(mark);
        }

        removeDuplicateShapes();

        // ----- text
        TextGrid textGrid = new TextGrid(grid);
        textGrid.removeNonText();
        textGrid.replaceBullets();

        TextGrid textGroupGrid = new TextGrid(textGrid);
        CellSet gaps = textGroupGrid.getAllBlanksBetweenCharacters();
        textGroupGrid.fillCellsWith(gaps, '|');
        CellSet nonBlank = textGroupGrid.getAllNonBlank();
        ArrayList<CellSet> textGroups = nonBlank.breakIntoDistinctBoundaries();

        Font font = FontMeasurer.instance().getFontFor(cellHeight);

        for (CellSet textGroupCellSet : textGroups) {
            TextGrid isolationGrid = new TextGrid(grid.getWidth(), grid.getHeight());
            textGrid.copyCellsTo(textGroupCellSet, isolationGrid);
            ArrayList<TextGrid.CellStringPair> strings = isolationGrid.findStrings();
            for (TextGrid.CellStringPair pair : strings) {
                Cell cell = pair.cell;
                String string = pair.string;
                Cell lastCell = new Cell(cell.x + string.length() - 1, cell.y);
                int minX = getCellMinX(cell);
                int y = getCellMaxY(cell);
                int maxX = getCellMaxX(lastCell);

                DiagramText textObject;
                boolean defaultFont = true;
                if (FontMeasurer.instance().getWidthFor(string, font) > maxX - minX) {
                    Font lessWideFont = FontMeasurer.instance().getFontFor(maxX - minX, string);
                    textObject = new DiagramText(minX, y, string, lessWideFont);
                    defaultFont = false;
                } else {
                    textObject = new DiagramText(minX, y, string, font);
                }
                textObject.centerVerticallyBetween(getCellMinY(cell), getCellMaxY(cell), defaultFont);

                int otherStart = isolationGrid.otherStringsStartInTheSameColumn(cell);
                int otherEnd = isolationGrid.otherStringsEndInTheSameColumn(lastCell);
                if (otherStart == 0 && otherEnd == 0) {
                    textObject.centerHorizontallyBetween(minX, maxX);
                } else if (otherEnd > 0 && otherStart == 0) {
                    textObject.alignRightEdgeTo(maxX);
                } else if (otherEnd > 0 && otherStart > 0) {
                    if (otherEnd > otherStart) textObject.alignRightEdgeTo(maxX);
                    else if (otherEnd == otherStart) textObject.centerHorizontallyBetween(minX, maxX);
                }
                addToTextObjects(textObject);
            }
        }

        // ----- text colour on dark backgrounds
        for (DiagramText textObject : textObjects) {
            DiagramShape shape = findSmallestShapeIntersecting(textObject.getBounds());
            if (shape != null && shape.getFillColor() != null && BitmapRenderer.isColorDark(shape.getFillColor())) {
                textObject.setColor(Color.white);
            }
        }

        // ----- connect line ends to anchors
        for (CompositeDiagramShape composite : compositeShapes) {
            composite.connectEndsToAnchors(workGrid, this);
        }

        if (options.processingOptions.performSeparationOfCommonEdges()) separateCommonEdges();

        // flatten composites into the shape list
        for (CompositeDiagramShape composite : compositeShapes) {
            for (DiagramShape s : composite.getShapes()) addToShapes(s);
        }
    }

    // ------------------------------------------------------------ helpers

    private ArrayList<CellSet> breakIntoDistinctBoundaries(TextGrid grid, CellSet set) {
        AbstractionGrid temp = new AbstractionGrid(grid, set);
        return temp.getDistinctShapes();
    }

    /** Finds the boundaries of all enclosed areas of the set (using the abstraction grid). */
    private ArrayList<CellSet> findClosedSetsByFilling(TextGrid workGrid, CellSet set) {
        ArrayList<CellSet> result = new ArrayList<CellSet>();
        AbstractionGrid abstraction = new AbstractionGrid(workGrid, set);
        TextGrid grid = abstraction.getCopyOfInternalBuffer();
        int w = grid.getWidth(), h = grid.getHeight();
        // mark the exterior
        grid.fillContinuousArea(0, 0, 'E');
        for (int y = 0; y < h; y++) {
            for (int x = 0; x < w; x++) {
                if (grid.isBlank(x, y)) {
                    CellSet boundary = grid.findBoundariesExpandingFrom(new Cell(x, y));
                    CellSet scaled = boundary.makeScaledOneThirdEquivalent();
                    result.add(scaled);
                }
            }
        }
        return result;
    }

    private void separateCommonEdges() {
        float offset = getMinimumOfCellDimension() / 5f;
        ArrayList<ShapeEdge> edges = new ArrayList<ShapeEdge>();
        for (DiagramShape shape : getAllDiagramShapes()) {
            if (!shape.isClosed()) continue;
            if (shape.getType() == DiagramShape.TYPE_ARROWHEAD || shape.getType() == DiagramShape.TYPE_POINT_MARKER) continue;
            edges.addAll(shape.getEdges());
        }
        ArrayList<ShapeEdge[]> pairs = new ArrayList<ShapeEdge[]>();
        int startIndex = 1;
        for (ShapeEdge edge1 : edges) {
            for (int k = startIndex; k < edges.size(); k++) {
                ShapeEdge edge2 = edges.get(k);
                if (edge1.touchesWith(edge2)) pairs.add(new ShapeEdge[]{edge1, edge2});
            }
            startIndex++;
        }
        ArrayList<ShapeEdge> moved = new ArrayList<ShapeEdge>();
        for (ShapeEdge[] pair : pairs) {
            if (!containsEdge(moved, pair[0])) { pair[0].moveInwardsBy(offset); moved.add(pair[0]); }
            if (!containsEdge(moved, pair[1])) { pair[1].moveInwardsBy(offset); moved.add(pair[1]); }
        }
    }

    private static boolean containsEdge(ArrayList<ShapeEdge> list, ShapeEdge e) {
        for (ShapeEdge x : list) if (x == e) return true;
        return false;
    }

    private ArrayList<DiagramShape> getAllDiagramShapes() {
        ArrayList<DiagramShape> all = new ArrayList<DiagramShape>();
        all.addAll(shapes);
        for (CompositeDiagramShape c : compositeShapes) all.addAll(c.getShapes());
        return all;
    }

    private void removeDuplicateShapes() {
        ArrayList<DiagramShape> originals = new ArrayList<DiagramShape>();
        for (DiagramShape shape : shapes) {
            boolean dup = false;
            for (DiagramShape o : originals) {
                if (o.equals(shape)) { dup = true; break; }
            }
            if (!dup) originals.add(shape);
        }
        shapes = originals;
    }

    public DiagramShape findSmallestShapeContaining(ShapePoint point) {
        DiagramShape containingShape = null;
        for (DiagramShape shape : shapes) {
            if (!shape.isClosed() || shape.getType() == DiagramShape.TYPE_ARROWHEAD) continue;
            if (shape.contains(point)) {
                if (containingShape == null) containingShape = shape;
                else if (shape.isSmallerThan(containingShape)) containingShape = shape;
            }
        }
        return containingShape;
    }

    public DiagramShape findSmallestShapeIntersecting(Rectangle2D rect) {
