    public int getCellMidY(Cell c) { return c.y * cellHeight + cellHeight / 2; }
    public int getCellMaxY(Cell c) { return c.y * cellHeight + cellHeight; }

    public Cell getCellFor(ShapePoint point) {
        if (point == null) throw new IllegalArgumentException("ShapePoint cannot be null");
        return new Cell((int) (point.x / cellWidth), (int) (point.y / cellHeight));
    }
