package ditaa;

import java.util.Comparator;

/** Sorts shapes so that larger shapes come first. */
public class ShapeAreaComparator implements Comparator<DiagramShape> {
    public int compare(DiagramShape s1, DiagramShape s2) {
        double a1 = s1.getArea(), a2 = s2.getArea();
        if (a1 > a2) return -1;
        if (a1 < a2) return 1;
        return 0;
    }
}
