        new OptDef("S", "no-shadows", false),
        new OptDef("s", "scale", true),
        new OptDef(null, "svg", false),
        new OptDef(null, "svg-font-url", true),
        new OptDef("T", "transparent", false),
        new OptDef("t", "tabs", true),
