        po.setAllCornersRound(cl.has("round-corners"));
        po.setPerformSeparationOfCommonEdges(!cl.has("no-separation"));
        ro.setDropShadows(!cl.has("no-shadows"));
        ro.setAntialias(!cl.has("no-antialias"));
        ro.setTransparent(cl.has("transparent"));
        ro.setFixedSlope(cl.has("fixed-slope"));
        po.setHtml(cl.has("html"));
        po.setSvg(cl.has("svg"));
        if (cl.has("svg-font-url")) ro.setSvgFontUrl(cl.value("svg-font-url"));

