        System.out.println("Reading file: " + filename);
        File inputFile = new File(filename);
        if (!inputFile.exists() || inputFile.isDirectory()) {
            System.err.println("Error: File " + filename + " does not exist");
            System.exit(1);
        }

        String toFilename;
        if (cl.args.size() >= 2) {
            toFilename = cl.args.get(1);
        } else {
            String ext = po.isSvg() ? ".svg" : ".png";
            toFilename = stripExtension(filename) + ext;
            if (!po.overwriteFiles()) toFilename = makeTargetUnique(toFilename);
        }

        TextGrid grid = new TextGrid();
        try {
            grid.loadFrom(filename, po);
        } catch (Exception e) {
            System.err.println("Error: Cannot open file " + filename + " for reading");
            System.exit(1);
