            BufferedImage image = BitmapRenderer.renderToImage(diagram, ro);
            try {
                File file = new File(toFilename);
                OutputStream out = new FileOutputStream(file);
                ImageIO.write(image, "png", out);
                out.close();
            } catch (Exception e) {
                System.err.println("Error: Cannot write to file " + toFilename);
                System.exit(1);
            }
        }

        long endTime = System.currentTimeMillis();
        long totalTime = (endTime - startTime) / 1000;
        System.out.println("Done in " + totalTime + "sec");
        System.exit(0);
    }

    static Color parseBackground(String hex) {
        if (hex.length() == 6) {
            try {
                int r = Integer.parseInt(hex.substring(0, 2), 16);
                int g = Integer.parseInt(hex.substring(2, 4), 16);
                int b = Integer.parseInt(hex.substring(4, 6), 16);
                return new Color(r, g, b);
            } catch (NumberFormatException e) { return null; }
        } else if (hex.length() == 8) {
            try {
                int r = Integer.parseInt(hex.substring(0, 2), 16);
                int g = Integer.parseInt(hex.substring(2, 4), 16);
                int b = Integer.parseInt(hex.substring(4, 6), 16);
                int a = Integer.parseInt(hex.substring(6, 8), 16);
                return new Color(r, g, b, a);
            } catch (NumberFormatException e) { return null; }
        }
        return null;
    }

    static String stripExtension(String filename) {
        int slash = Math.max(filename.lastIndexOf('/'), filename.lastIndexOf(File.separatorChar));
        int dot = filename.lastIndexOf('.');
        if (dot > slash) return filename.substring(0, dot);
        return filename;
    }

    static String makeTargetUnique(String toFilename) {
        File file = new File(toFilename);
        if (!file.exists()) return toFilename;
        String base = stripExtension(toFilename);
        String ext = toFilename.substring(base.length());
        int i = 2;
        while (true) {
            String candidate = base + "_" + i + ext;
            if (!new File(candidate).exists()) return candidate;
            i++;
        }
    }
}
