package ditaa;

import java.awt.image.BufferedImage;
import java.io.*;
import java.nio.file.Files;
import java.util.*;
import java.util.regex.*;
import javax.imageio.ImageIO;

public class HTMLConverter {

    private static final Pattern prePattern = Pattern.compile(
        "<pre\\s[^>]*?class\\s*=\\s*[\"']textdiagram[\"'][^>]*>(.*?)</pre>",
        Pattern.CASE_INSENSITIVE | Pattern.DOTALL);
    private static final Pattern idPattern = Pattern.compile("\\sid\\s*=\\s*[\"']([^\"']*)[\"']", Pattern.CASE_INSENSITIVE);

    public static void convertHTMLFile(String filename, String targetFilename, String imageBaseFilename, String imageDirName, ConversionOptions options) throws IOException {
        System.out.print("Converting HTML file (" + filename + " -> " + targetFilename + ")... ");
        File file = new File(filename);
        byte[] bytes = Files.readAllBytes(file.toPath());
        String html = TextGrid.decodeBytes(bytes);

        HashMap<String, String> diagramTexts = new HashMap<String, String>();
        StringBuilder out = new StringBuilder();
        Matcher m = prePattern.matcher(html);
        int last = 0;
        int index = 1;
        while (m.find()) {
            String tag = html.substring(m.start(), m.start(1));
            String text = m.group(1);
            Matcher idm = idPattern.matcher(tag);
            String name;
            if (idm.find()) name = idm.group(1);
            else name = imageBaseFilename + "_" + (index++);
            String url = imageDirName + "/" + name + ".png";
            diagramTexts.put(url, text);
            out.append(html, last, m.start());
            out.append("<img src=\"").append(url).append("\" />");
            last = m.end();
        }
        out.append(html.substring(last));

        FileOutputStream fos = new FileOutputStream(targetFilename);
        fos.write(encodeString(out.toString()));
        fos.close();
        System.out.println("done");

        System.out.println("Generating diagrams... ");
        String parent = file.getParent();
        File imageDir = new File(parent, imageDirName);
        if (!imageDir.exists()) {
            if (parent == null || !imageDir.mkdir()) {
                System.out.println("Could not create directory " + imageDirName);
                return;
            }
        }

        for (Map.Entry<String, String> entry : diagramTexts.entrySet()) {
            String url = entry.getKey();
            String text = entry.getValue();
            String imageName = url.substring(url.indexOf('/') + 1);
            File imageFile = new File(imageDir, imageName);
            if (imageFile.exists() && !options.processingOptions.overwriteFiles()) {
                System.out.println("Error: Cannot overwrite file " + url + ", file already exists. Use the --overwrite option if you would like to allow file overwrite.");
                continue;
            }
            TextGrid grid = new TextGrid();
            grid.initialiseWithText(text, options.processingOptions);
            Diagram diagram = new Diagram(grid, options);
            BufferedImage image = BitmapRenderer.renderToImage(diagram, options.renderingOptions);
            try {
                OutputStream os = new FileOutputStream(imageFile);
                ImageIO.write(image, "png", os);
                os.close();
            } catch (IOException e) {
                System.err.println("Error: Cannot write to file " + imageFile.getPath());
                continue;
            }
            System.out.println("\t" + imageFile.getAbsolutePath());
        }
        System.out.println("\n...done");
    }

    private static byte[] encodeString(String s) {
        byte[] b = new byte[s.length()];
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            b[i] = (byte) (c < 0x80 ? c : '?');
        }
        return b;
    }
}
