package ditaa;

import java.util.Comparator;

/**
 * Sorts shapes so that larger shapes are rendered first.  Storage shapes are always
 * rendered before anything else; among themselves the lower ones come first.
 */
public class ShapeAreaComparator implements Comparator<DiagramShape> {
    public int compare(DiagramShape s1, DiagramShape s2) {
        boolean st1 = s1.getType() == DiagramShape.TYPE_STORAGE;
        boolean st2 = s2.getType() == DiagramShape.TYPE_STORAGE;
        if (st1 && !st2) return -1;
        if (st2 && !st1) return 1;
        if (st1 && st2) {
            double y1 = s1.getBounds().getMaxY(), y2 = s2.getBounds().getMaxY();
            if (y1 > y2) return -1;
            if (y1 < y2) return 1;
            return 0;
        }
        double a1 = s1.getArea(), a2 = s2.getArea();
        if (a1 > a2) return -1;
        if (a1 < a2) return 1;
        return 0;
    }
}
