            if random.random() < 0.5: put(x+length, y, random.choice(['>','>','*','+']))
            if random.random() < 0.3: put(x-1, y, '<')
        else:
            for k in range(length): put(x, y+k, '|')
            if random.random() < 0.5: put(x, y+length, random.choice(['v','V','*','+']))
            if random.random() < 0.3: put(x, y-1, '^')
    # loose text
